```php
<?php
/*
 * fasta — exact reproduction of the Computer Language Benchmarks Game
 * "fasta" output, streamed to stdout.
 *
 *   >ONE Homo sapiens alu          + 2N chars: 287-char ALU, repeated
 *   >TWO IUB ambiguity codes       + 3N chars: LCG random, IUB table
 *   >THREE Homo sapiens frequency  + 5N chars: LCG random, human table
 *
 * Every sequence is wrapped at 60 columns; every line ends with "\n".
 *
 * Generator: seed = (seed*3877 + 29573) mod 139968, initial seed 42, shared
 * and advanced across BOTH random sections.  Each draw advances the seed
 * first, then uses r = seed/139968 and emits the first symbol whose running
 * cumulative probability is strictly greater than r.
 *
 * Performance: this LCG has full period 139968 (Hull-Dobell theorem:
 * 139968 = 2^6*3^7; 3877-1 = 2^2*3*17*19 is divisible by 2, 3 and 4; and
 * gcd(29573, 139968) = 1).  The drawn values — and therefore each random
 * section's symbol stream — repeat exactly with period 139968.  The program
 * runs the genuine generator for one full period per table (bit-exact by
 * construction) and materialises the huge sequences by repeating that
 * period in large pre-wrapped blocks: output is byte-identical to a naive
 * per-draw implementation while PHP-level work per character is O(1).
 */

error_reporting(E_ALL);
ini_set('display_errors', 'stderr');            /* keep stdout pristine */

define('IM', 139968);                           /* LCG modulus          */
define('IA', 3877);                             /* LCG multiplier       */
define('IC', 29573);                            /* LCG increment        */

$n = (int)($argv[1] ?? 0);

/**
 * One full period (IM symbols) of the random stream for a frequency table,
 * continuing the shared LCG state $seed.  Per-draw selection is exactly the
 * reference rule: advance seed, r = seed/IM, first cumulative > r.
 */
function makePeriod(array $chars, array $probs, int &$seed): string
{
    $cum = [];                                  /* running cumulative    */
    $c = 0.0;
    foreach ($probs as $p) { $c += $p; $cum[] = $c; }
    $last = count($chars) - 1;

    /* symbol for every possible seed value; r = v/IM grows with v, so the
       selected index only moves forward */
    $map = str_repeat('?', IM);
    $p = 0;
    for ($v = 0; $v < IM; $v++) {
        $r = $v / IM;
        while ($p < $last && $cum[$p] <= $r) { $p++; }
        $map[$v] = $chars[$p];
    }

    /* roll one full period of the generator */
    $out = str_repeat(' ', IM);
    $s = $seed;
    for ($k = 0; $k < IM; $k++) {
        $s = ($s * IA + IC) % IM;
        $out[$k] = $map[$s];
    }
    $seed = $s;
    return $out;
}

/**
 * Emit $total characters formed by cycling $period, wrapped at 60 columns.
 * Streams in large line-aligned blocks: flat memory, few I/O calls.
 */
function emitSeq(string $period, int $total): void
{
    if ($total <= 0) { return; }
    $pl = strlen($period);
    if ($pl === 0) { return; }

    if ($total <= $pl) {                        /* short sequence: direct */
        echo chunk_split(substr($period, 0, $total), 60, "\n");
        return;
    }

    /* block = $reps copies of the period; its length must be a multiple of
       60 so that repeated blocks stay on 60-column line boundaries */
    $g = $pl; $b = 60;
    while ($b) { $t = $g % $b; $g = $b; $b = $t; }          /* gcd(pl,60) */
    $step = intdiv(60, $g);
    $need = $total < 650000 ? $total : 650000;
    $reps = intdiv((int)ceil($need / $pl) + $step - 1, $step) * $step;

    $blockRaw = str_repeat($period, $reps);
    $blockLen = $pl * $reps;
    $block    = chunk_split($blockRaw, 60, "\n");

    $full = intdiv($total, $blockLen);
    for ($i = 0; $i < $full; $i++) { echo $block; }

    $rem = $total - $full * $blockLen;
    if ($rem > 0) { echo chunk_split(substr($blockRaw, 0, $rem), 60, "\n"); }
}

$alu =
    'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' .
    'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' .
    'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' .
    'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' .
    'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

$seed = 42;

$iubPeriod = makePeriod(
    ['a', 'c', 'g', 't', 'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y'],
    [0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02],
    $seed
);

$hsPeriod = makePeriod(
    ['a', 'c', 'g', 't'],
    [0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008],
    $seed
);

echo ">ONE Homo sapiens alu\n";
emitSeq($alu, 2 * $n);

echo ">TWO IUB ambiguity codes\n";
emitSeq($iubPeriod, 3 * $n);

/* THREE shares the seed: its first draw is global draw number 3N+1, i.e.
   period offset (3N mod 139968) into the Homo sapiens period. */
$o = (3 * $n) % IM;
$hsRot = $o ? substr($hsPeriod, $o) . substr($hsPeriod, 0, $o) : $hsPeriod;

echo ">THREE Homo sapiens frequency\n";
emitSeq($hsRot, 5 * $n);
