```php
<?php
/**
 * k-nucleotide benchmark
 *
 * Reads FASTA from stdin, extracts the THIRD sequence (header containing
 * "THREE", falling back to the third record), normalizes to upper case and
 * reports:
 *   - 1-mer frequencies  (sorted by count desc, ties alphabetical)
 *   - 2-mer frequencies  (sorted by count desc, ties alphabetical)
 *   - occurrence counts for specific fragments
 */

$data = stream_get_contents(STDIN);
if ($data === false) {
    $data = '';
}

// ---- Parse FASTA ----
$lines = preg_split('/\r\n|\r|\n/', $data);
$seqs = [];
$heads = [];
$cur = -1;
foreach ($lines as $line) {
    if ($line === '') {
        continue;
    }
    if ($line[0] === '>') {
        $cur++;
        $heads[$cur] = substr($line, 1);
        $seqs[$cur] = '';
    } elseif ($line[0] === ';') {
        // old-style comment line, ignore
        continue;
    } elseif ($cur >= 0) {
        $seqs[$cur] .= $line;
    }
}

// ---- Select the THREE sequence ----
$chosen = null;
foreach ($heads as $i => $h) {
    if (strpos($h, 'THREE') !== false) {
        $chosen = $i;
        break;
    }
}
if ($chosen === null) {
    if (count($seqs) >= 3) {
        $chosen = 2;
    } else {
        $keys = array_keys($seqs);
        $chosen = empty($keys) ? null : end($keys);
    }
}

$s = '';
if ($chosen !== null) {
    $s = strtoupper($seqs[$chosen]);
}
$n = strlen($s);

// ---- 1-mer frequencies ----
$one = [
    'A' => substr_count($s, 'A'),
    'C' => substr_count($s, 'C'),
    'G' => substr_count($s, 'G'),
    'T' => substr_count($s, 'T'),
];

// ---- 2-mer frequencies (overlapping counts) ----
$two = [];
$alpha = ['A', 'C', 'G', 'T'];
foreach ($alpha as $a) {
    foreach ($alpha as $b) {
        $k = $a . $b;
        $c = 0;
        $pos = -1;
        while (($pos = strpos($s, $k, $pos + 1)) !== false) {
            $c++;
        }
        $two[$k] = $c;
    }
}

// ---- Sorting helper: count descending, then name ascending ----
$cmp = function ($ka, $va, $kb, $vb) {
    if ($va !== $vb) {
        return $vb <=> $va; // count desc
    }
    return strcmp($ka, $kb); // name asc
};

// sort 1-mers
$oneKeys = array_keys($one);
usort($oneKeys, function ($a, $b) use ($one, $cmp) {
    return $cmp($a, $one[$a], $b, $one[$b]);
});

// sort 2-mers
$twoKeys = array_keys($two);
usort($twoKeys, function ($a, $b) use ($two, $cmp) {
    return $cmp($a, $two[$a], $b, $two[$b]);
});

// ---- Output ----
$den = $n > 0 ? $n : 1;
foreach ($oneKeys as $k) {
    printf("%s %.3f\n", $k, $one[$k] * 100.0 / $den);
}
foreach ($twoKeys as $k) {
    printf("%s %.3f\n", $k, $two[$k] * 100.0 / $den);
}

// ---- Specific fragment counts ----
$frags = [
    'GGT',
    'GGTA',
    'GGTATT',
    'GGTATTTTAATT',
    'GGTATTTTAATTTATAGT',
];
foreach ($frags as $f) {
    // These fragments cannot self-overlap, so substr_count is exact.
    printf("%d\t%s\n", substr_count($s, $f), $f);
}
```

