                /* z <- z^2 + c, up to 50 iterations, escape radius 2. */
                $zr = 0.0;
                $zi = 0.0;
                $tr = 0.0;
                $ti = 0.0;
                $bit = 1;
                $k = 25;
                while ($k--) {
                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    if ($tr + $ti > 4.0) {
