        $acc = ($acc << 1) | $bit;
        if (++$bc === 8) {
            $buf .= chr($acc);
            $acc = 0;
            $bc = 0;
        }
    }

    if ($bc !== 0) {
        $buf .= chr($acc << (8 - $bc));
    }

