```php
<?php
/**
 * Mandelbrot benchmark — renders an N×N image of the Mandelbrot set
 * (z <- z^2 + c, escape radius 2, max 50 iterations) and writes it to
 * standard output as a binary PBM (P4, one bit per pixel).
 * Usage: php mandelbrot.php N
 */

$n = (int) ($argv[1] ?? 0);

$out = defined('STDOUT') ? STDOUT : fopen('php://output', 'wb');

// Column coordinates (real part of c): cr = 2x/N - 1.5, x = 0..N-1.
// Computed once and reused by every row.
$crs = array();
for ($x = 0; $x < $n; ++$x) {
    $crs[] = 2.0 * $x / $n - 1.5;
}

fwrite($out, "P4\n" . $n . ' ' . $n . "\n");

$buf = ''; // output accumulator, flushed periodically

for ($y = 0; $y < $n; ++$y) {
    $ci = 2.0 * $y / $n - 1.0; // imaginary part of c for this row
    $ci2 = $ci * $ci;
    $ci2q = 0.25 * $ci2;
    $acc = 0;  // byte under construction (MSB = leftmost pixel)
    $bc = 0;   // bits accumulated in $acc

    foreach ($crs as $cr) {
        // Points inside the main cardioid or the period-2 bulb can never
        // escape, so they belong to the set.  Testing this directly is
        // exact: the floating-point slack of the test (~1e-16) is far
        // smaller than the distance at which a point can still escape
        // within 50 iterations, so the rendered bits are identical to
        // plain iteration, just much cheaper for interior pixels.
        $t = $cr - 0.25;
        $q = $t * $t + $ci2;
        if ($q * ($q + $t) <= $ci2q) {
            $bit = 1;
        } else {
            $u = $cr + 1.0;
            if ($u * $u + $ci2 <= 0.0625) {
                $bit = 1;
            } else {
                // Iterate z <- z^2 + c, up to 50 iterations.
                // The escape test runs after every second step: once
                // |z|^2 exceeds 4 it can never drop back (|c| <= sqrt(3.25) < 2
                // everywhere in the sampled window), so the resulting bit is
                // identical to testing after every single step.
                $zr = 0.0;
                $zi = 0.0;
                $tr = 0.0; // zr^2
                $ti = 0.0; // zi^2
                $bit = 1;
                $k = 25;
                while ($k--) {
                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    if ($tr + $ti > 4.0) {
                        $bit = 0;
                        break;
                    }
                }
            }
        }

        $acc = ($acc << 1) | $bit;
        if (++$bc === 8) {
            $buf .= chr($acc);
            $acc = 0;
            $bc = 0;
        }
    }

    if ($bc !== 0) { // pad final partial byte of the row with zero bits
        $buf .= chr($acc << (8 - $bc));
    }

    if (($y & 255) === 255) {
        fwrite($out, $buf);
        $buf = '';
    }
}

fwrite($out, $buf);
