```php
<?php
/*
 * Mandelbrot benchmark (binary PBM output).
 *
 * Renders the Mandelbrot set for c = (2x/N - 1.5) + (2y/N - 1)i,
 * x,y in [0, N), using z <- z^2 + c with escape radius 2 and at most
 * 50 iterations, and writes a P4 (binary PBM) bitmap to stdout:
 * pixels inside the set are black (bit 1), escaped pixels white (bit 0).
 *
 * Usage: php mandelbrot.php N
 */

$n = (int) ($argv[1] ?? 0);

$out = defined('STDOUT') ? STDOUT : fopen('php://output', 'wb');

// Real part of c for every column; computed once, reused by all rows.
$crs = array();
for ($x = 0; $x < $n; ++$x) {
    $crs[] = 2.0 * $x / $n - 1.5;
}

fwrite($out, "P4\n" . $n . ' ' . $n . "\n");

$buf = '';

for ($y = 0; $y < $n; ++$y) {
    $ci = 2.0 * $y / $n - 1.0;
    $ci2 = $ci * $ci;
    $ci2q = 0.25 * $ci2;
    $acc = 0;
    $bc = 0;

    foreach ($crs as $cr) {
        // Fast path: a point inside the main cardioid or inside the
        // period-2 bulb belongs to the set and can never escape.
        $t = $cr - 0.25;
        $q = $t * $t + $ci2;
        if ($q * ($q + $t) <= $ci2q) {
            $bit = 1;
        } else {
            $u = $cr + 1.0;
            if ($u * $u + $ci2 <= 0.0625) {
                $bit = 1;
            } else {
                // Plain iteration.  The escape test runs after every
                // second step: with |c| <= sqrt(3.25) < 2 on this window,
                // |z|^2 > 4 can never fall back to <= 4, so the outcome
                // is identical to testing after every step.
                $zr = 0.0;
                $zi = 0.0;
                $tr = 0.0;
                $ti = 0.0;
                $bit = 1;
                $k = 25;
                while ($k--) {
                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    $zi *= $zr;
                    $zi += $zi;
                    $zi += $ci;
                    $zr = $tr - $ti + $cr;
                    $tr = $zr * $zr;
                    $ti = $zi * $zi;

                    if ($tr + $ti > 4.0) {
                        $bit = 0;
                        break;
                    }
                }
            }
        }

        $acc = ($acc << 1) | $bit;
        if (++$bc === 8) {
            $buf .= chr($acc);
            $acc = 0;
            $bc = 0;
        }
    }

    if ($bc !== 0) {
        $buf .= chr($acc << (8 - $bc));
    }

    if (strlen($buf) >= 1048576) {
        fwrite($out, $buf);
        $buf = '';
    }
}

fwrite($out, $buf);
```

