<?php
// reverse-complement
// Reads FASTA-formatted DNA from stdin and writes the reverse complement to
// stdout, preserving each FASTA header verbatim and the original line
// wrapping: for every record the sequence lines are emitted in reverse order
// with each line reversed and complemented, so every output line mirrors an
// input line of the same record (the standard behaviour for this benchmark).

ini_set('memory_limit', '-1');
ini_set('display_errors', 'stderr');

// N arrives as the first command-line argument; the output itself depends
// only on the FASTA data piped in on stdin, so N is parsed but not used.
$n = isset($argv[1]) ? (int)$argv[1] : 0;

$stdin = defined('STDIN') ? STDIN : fopen('php://stdin', 'rb');
$data  = $stdin ? stream_get_contents($stdin) : '';
if (!is_string($data) || $data === '') {
    exit(0);
}

// Normalize line endings (no-op for the usual LF-only stream).
if (strpos($data, "\r") !== false) {
    $data = str_replace("\r", '', $data);
}

// IUPAC complement table in strtr's fast byte-map form (single C-level pass):
// A<->T, C<->G, U->A, R<->Y, K<->M, B<->V, D<->H, S/W/N unchanged.
$from = 'ATCGURYKMBVDHSWNatcgurykmbvdhswn';
$to   = 'TAGCAYRMKVBHDSWNtagcayrmkvbhdswn';

// Locate the start offset of every header line ('>' at beginning of a line).
$heads = array();
if ($data[0] === '>') {
    $heads[] = 0;
}
$p = 0;
while (($p = strpos($data, "\n>", $p)) !== false) {
    $heads[] = $p + 1;
    $p += 1;
}
$nRec = count($heads);

if ($nRec === 0) {
    // No FASTA header present: treat the whole input as one bare sequence.
    if ($data[-1] === "\n") {
        $data = substr($data, 0, -1);
    }
    if ($data !== '') {
        echo strtr(strrev($data), $from, $to), "\n";
    }
    exit(0);
}

for ($j = 0; $j < $nRec; $j++) {
    $hStart = $heads[$j];
    $nl = strpos($data, "\n", $hStart);

    if ($nl === false) {
        // Degenerate tail: header line without newline and no sequence.
        echo substr($data, $hStart), "\n";
        continue;
    }

    // Header line, verbatim.
    echo substr($data, $hStart, $nl - $hStart), "\n";

    $bodyStart = $nl + 1;
    if ($j + 1 < $nRec) {
        // Body excludes the newline that precedes the next header line.
        $blen = ($heads[$j + 1] - 1) - $bodyStart;
        if ($blen > 0) {
            $body = substr($data, $bodyStart, $blen);
            // Reversing the multi-line body mirrors the line breaks, which
            // preserves the original line wrapping of the record.
            echo strtr(strrev($body), $from, $to), "\n";
        }
    } else {
        $body = (string)substr($data, $bodyStart);
        if ($body === '') {
            continue;
        }
        if ($body[-1] === "\n") {
            $body = substr($body, 0, -1);
        }
        echo strtr(strrev($body), $from, $to), "\n";
    }
}
