               perm[i] = perm[k-i];
               perm[k-i] = temp;
            }
            flipsCount++;
         }

         maxFlipsCount = max(maxFlipsCount, flipsCount);
         checksum += permCount % 2 == 0 ? flipsCount : -flipsCount;

