int fannkuch(int n) {
   int *perm1 = malloc(n * sizeof(int));
   int *count = malloc(n * sizeof(int));
   int *perm = malloc(n * sizeof(int));
   int maxFlipsCount = 0;
   int permCount = 0;
   int checksum = 0;
   int i;

   for (i = 0; i < n; i++)
      perm1[i] = i;
