         for (i = 0; i < n; i++)
            perm[i] = perm1[i];
         int flipsCount = 0;
         int k;

         while ((k = perm[0]) != 0) {
            int k2 = (k+1) >> 1;
            for (i = 0; i<k2; i++) {
               int temp = perm[i];
               perm[i] = perm[k-i];
               perm[k-i] = temp;
            }
            flipsCount++;
         }

         maxFlipsCount = max(maxFlipsCount, flipsCount);
         checksum += permCount % 2 == 0 ? flipsCount : -flipsCount;

         while (1) {
            if (r == n) {
               printf("%d\n", checksum);
               return maxFlipsCount;
            }
            int perm0 = perm1[0];
            int i = 0;
            while (i < r) {
               int j = i - 1;
               perm1[j] = perm1[i];
               i++;
            }
            perm1[r-1] = perm0;
            ...
         }
      }
   }
}
```

